mapper.select:
select distinct PROD_SERIES from REP_PROD_INFO
STATUS='E' and PROD_SERIES is not null and REP_PROD_TYPE in ('01','02')
and PD_STATUS=#{prodStatus,jdbcType=VARCHAR}
and ISSUING_WAY=#{issueType,jdbcType=VARCHAR}
order by PROD_SERIES

select distinct case when prod.REP_PROD_TYPE = '03' then pprod.PROD_NAME else prod.PROD_NAME end from REP_PROD_INFO prod left join V_REP_PROD_INFO pprod on prod.p_prod_id = pprod.prod_id
prod.rep_prod_type ='03' and prod.STATUS='E' and prod.PROD_SERIES is not null
and prod.PD_STATUS=#{prodStatus,jdbcType=VARCHAR}
and prod.ISSUING_WAY=#{issueType,jdbcType=VARCHAR}
and prod.PROD_SERIES=#{prodSeries,jdbcType=VARCHAR}
